import React, { useState } from 'react';
import { useTheme } from '../context/ThemeContext';
import { loginUser, signupUser } from '../utils/supabase';

export default function Login({ onLogin }) {
  const { t, mode, toggleTheme } = useTheme();
  const [isSignup, setIsSignup] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = async () => {
    if (!email || !password) return setError('Please fill in all fields');
    setLoading(true);
    setError('');
    try {
      if (isSignup) {
        await signupUser(email, password);
        setError('✅ Account created! You can now log in.');
        setIsSignup(false);
      } else {
        const data = await loginUser(email, password);
        onLogin(data.user);
      }
    } catch (err) {
      setError(err.message);
    }
    setLoading(false);
  };

  return (
    <div style={{
      minHeight: '100vh', background: t.bg,
      display: 'flex', alignItems: 'center', justifyContent: 'center',
      position: 'relative'
    }}>
      {/* Theme toggle */}
      <button
        onClick={toggleTheme}
        style={{
          position: 'absolute', top: '20px', right: '20px',
          background: t.bgTertiary, border: `1px solid ${t.border}`,
          borderRadius: '8px', width: '36px', height: '36px',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          color: t.textSecondary, fontSize: '16px'
        }}
      >
        {mode === 'dark' ? '☀️' : '🌙'}
      </button>

      <div style={{ width: '100%', maxWidth: '400px', padding: '0 24px' }}>

        {/* Logo */}
        <div style={{ textAlign: 'center', marginBottom: '40px' }}>
          <div style={{
            width: '48px', height: '48px', borderRadius: '12px',
            background: t.accent, display: 'flex', alignItems: 'center',
            justifyContent: 'center', margin: '0 auto 16px', fontSize: '24px'
          }}>
            ⚡
          </div>
          <h1 style={{ color: t.textPrimary, fontSize: '24px', fontWeight: 700, margin: '0 0 4px' }}>
            ContentAI
          </h1>
          <p style={{ color: t.textSecondary, fontSize: '14px' }}>
            {isSignup ? 'Create your account' : 'Sign in to your account'}
          </p>
        </div>

        {/* Form */}
        <div style={{
          background: t.bgCard, border: `1px solid ${t.border}`,
          borderRadius: '12px', padding: '24px',
          boxShadow: t.shadowCard
        }}>

          {error && (
            <div style={{
              padding: '10px 14px', borderRadius: '8px', marginBottom: '16px',
              background: error.includes('✅') ? t.successSubtle : t.dangerSubtle,
              color: error.includes('✅') ? t.success : t.danger,
              fontSize: '13px', border: `1px solid ${error.includes('✅') ? t.success + '40' : t.danger + '40'}`
            }}>
              {error}
            </div>
          )}

          <div style={{ marginBottom: '16px' }}>
            <label style={{ color: t.textSecondary, fontSize: '13px', fontWeight: 500, display: 'block', marginBottom: '6px' }}>
              Email address
            </label>
            <input
              type="email"
              value={email}
              onChange={e => setEmail(e.target.value)}
              placeholder="you@example.com"
              style={{
                width: '100%', padding: '10px 12px',
                background: t.bgSecondary, border: `1px solid ${t.border}`,
                borderRadius: '8px', color: t.textPrimary, fontSize: '14px',
                outline: 'none', transition: 'border-color 0.15s', boxSizing: 'border-box'
              }}
              onFocus={e => e.target.style.borderColor = t.accent}
              onBlur={e => e.target.style.borderColor = t.border}
            />
          </div>

          <div style={{ marginBottom: '20px' }}>
            <label style={{ color: t.textSecondary, fontSize: '13px', fontWeight: 500, display: 'block', marginBottom: '6px' }}>
              Password
            </label>
            <div style={{ position: 'relative' }}>
              <input
                type={showPassword ? 'text' : 'password'}
                value={password}
                onChange={e => setPassword(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleSubmit()}
                placeholder="••••••••"
                style={{
                  width: '100%', padding: '10px 40px 10px 12px',
                  background: t.bgSecondary, border: `1px solid ${t.border}`,
                  borderRadius: '8px', color: t.textPrimary, fontSize: '14px',
                  outline: 'none', transition: 'border-color 0.15s', boxSizing: 'border-box'
                }}
                onFocus={e => e.target.style.borderColor = t.accent}
                onBlur={e => e.target.style.borderColor = t.border}
              />
              <button
                onClick={() => setShowPassword(!showPassword)}
                style={{
                  position: 'absolute', right: '10px', top: '50%',
                  transform: 'translateY(-50%)', background: 'none',
                  border: 'none', color: t.textMuted, fontSize: '14px', padding: '4px'
                }}
              >
                {showPassword ? '🙈' : '👁️'}
              </button>
            </div>
          </div>

          <button
            onClick={handleSubmit}
            disabled={loading}
            style={{
              width: '100%', padding: '11px',
              background: loading ? t.textMuted : t.accent,
              color: 'white', border: 'none', borderRadius: '8px',
              fontSize: '14px', fontWeight: 600,
              cursor: loading ? 'not-allowed' : 'pointer',
              transition: 'background 0.15s'
            }}
            onMouseEnter={e => { if (!loading) e.target.style.background = t.accentHover; }}
            onMouseLeave={e => { if (!loading) e.target.style.background = t.accent; }}
          >
            {loading ? 'Please wait...' : isSignup ? 'Create Account' : 'Sign In'}
          </button>
        </div>

        <p style={{ textAlign: 'center', color: t.textSecondary, fontSize: '13px', marginTop: '16px' }}>
          {isSignup ? 'Already have an account?' : "Don't have an account?"}
          <span
            onClick={() => { setIsSignup(!isSignup); setError(''); }}
            style={{ color: t.accent, cursor: 'pointer', marginLeft: '6px', fontWeight: 500 }}
          >
            {isSignup ? 'Sign in' : 'Sign up'}
          </span>
        </p>
      </div>
    </div>
  );
}
